mapper.select:
SELECT DATE(start_time) AS day, IFNULL(SUM(fee), 0) AS income FROM course
WHERE user_id = #{userId} AND end_time < NOW() AND start_time >= #{start} AND start_time < #{end}
GROUP BY DATE(start_time) ORDER BY day

SELECT c.student_name AS name, IFNULL(SUM(c.fee), 0) AS value FROM course c
WHERE c.user_id = #{userId} AND c.end_time < NOW() AND c.start_time >= #{start} AND c.start_time < #{end}
GROUP BY c.student_name ORDER BY value DESC

SELECT IFNULL(c.stage, '未分类') AS name, IFNULL(SUM(c.fee), 0) AS value FROM course c
WHERE c.user_id = #{userId} AND c.end_time < NOW() AND c.start_time >= #{start} AND c.start_time < #{end}
GROUP BY c.stage ORDER BY value DESC
